#!/usr/bin/env python3\n\"\"\"\nAPI Testing Script for PluraAI Backend\nTests the inference endpoint with sample images\n\"\"\"\n\nimport requests\nimport json\nimport os\nfrom PIL import Image\nimport numpy as np\n\ndef create_test_image(filename=\"test_xray.jpg\", size=(512, 512)):\n    \"\"\"Create a dummy chest X-ray like image for testing\"\"\"\n    # Create a grayscale image that looks like an X-ray\n    img_array = np.random.randint(50, 200, size + (3,), dtype=np.uint8)\n    \n    # Add some chest-like structure\n    center_x, center_y = size[0] // 2, size[1] // 2\n    for i in range(size[0]):\n        for j in range(size[1]):\n            # Create ribcage-like pattern\n            dist_from_center = ((i - center_x) ** 2 + (j - center_y) ** 2) ** 0.5\n            if dist_from_center < size[0] // 3:\n                img_array[i, j] = img_array[i, j] * 0.7  # Darker lung area\n    \n    img = Image.fromarray(img_array.astype('uint8'))\n    img.save(filename)\n    return filename\n\ndef test_api_endpoint(base_url=\"http://localhost:8000\"):\n    \"\"\"Test the prediction API endpoint\"\"\"\n    \n    print(\"🧪 Testing PluraAI Backend API\")\n    print(\"=\" * 40)\n    \n    # Create test image\n    test_image = create_test_image()\n    print(f\"✅ Created test image: {test_image}\")\n    \n    # Test endpoint\n    url = f\"{base_url}/api/predict/\"\n    \n    try:\n        with open(test_image, 'rb') as f:\n            files = {'image': f}\n            print(f\"📡 Sending request to: {url}\")\n            \n            response = requests.post(url, files=files, timeout=30)\n            \n            print(f\"📊 Response Status: {response.status_code}\")\n            \n            if response.status_code == 200:\n                result = response.json()\n                print(\"✅ API Response:\")\n                print(json.dumps(result, indent=2))\n                \n                # Validate response structure\n                required_fields = ['prediction', 'confidence', 'inference_time', 'status']\n                missing_fields = [field for field in required_fields if field not in result]\n                \n                if missing_fields:\n                    print(f\"⚠️  Missing fields: {missing_fields}\")\n                else:\n                    print(\"✅ All required fields present\")\n                    \n                    # Validate prediction values\n                    if result['prediction'] in ['Normal', 'Pneumonia']:\n                        print(\"✅ Valid prediction class\")\n                    else:\n                        print(f\"❌ Invalid prediction: {result['prediction']}\")\n                        \n                    if 0 <= result['confidence'] <= 1:\n                        print(\"✅ Valid confidence score\")\n                    else:\n                        print(f\"❌ Invalid confidence: {result['confidence']}\")\n                        \n            else:\n                print(f\"❌ API Error: {response.status_code}\")\n                print(response.text)\n                \n    except requests.exceptions.ConnectionError:\n        print(\"❌ Connection Error: Is the server running on localhost:8000?\")\n        print(\"   Start server with: python manage.py runserver\")\n    except Exception as e:\n        print(f\"❌ Error: {str(e)}\")\n    finally:\n        # Clean up test image\n        if os.path.exists(test_image):\n            os.remove(test_image)\n            print(f\"🧹 Cleaned up: {test_image}\")\n\ndef test_error_cases(base_url=\"http://localhost:8000\"):\n    \"\"\"Test API error handling\"\"\"\n    \n    print(\"\\n🧪 Testing Error Cases\")\n    print(\"=\" * 40)\n    \n    url = f\"{base_url}/api/predict/\"\n    \n    # Test 1: No image\n    print(\"Test 1: No image uploaded\")\n    try:\n        response = requests.post(url)\n        print(f\"Status: {response.status_code} (Expected: 400)\")\n        if response.status_code == 400:\n            print(\"✅ Correctly rejected empty request\")\n    except Exception as e:\n        print(f\"❌ Error: {e}\")\n    \n    # Test 2: Invalid file type\n    print(\"\\nTest 2: Invalid file type\")\n    try:\n        # Create a text file\n        with open(\"test.txt\", \"w\") as f:\n            f.write(\"This is not an image\")\n        \n        with open(\"test.txt\", \"rb\") as f:\n            files = {'image': f}\n            response = requests.post(url, files=files)\n            print(f\"Status: {response.status_code} (Expected: 400)\")\n            if response.status_code == 400:\n                print(\"✅ Correctly rejected invalid file type\")\n        \n        os.remove(\"test.txt\")\n    except Exception as e:\n        print(f\"❌ Error: {e}\")\n\nif __name__ == \"__main__\":\n    print(\"PluraAI Backend API Test Suite\")\n    print(\"==============================\\n\")\n    \n    # Test main functionality\n    test_api_endpoint()\n    \n    # Test error handling\n    test_error_cases()\n    \n    print(\"\\n🎉 Testing completed!\")